package com.fooddelivery.mail.controller;
import com.fooddelivery.mail.entity.MailDelivery;import com.fooddelivery.mail.service.MailService;import jakarta.validation.Valid;import jakarta.validation.constraints.Email;import jakarta.validation.constraints.NotBlank;import jakarta.validation.constraints.Size;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/internal/mail") public class MailController{private final MailService service;private final String key;public MailController(MailService s,@Value("${mail.internal-key}")String k){service=s;key=k;}@PostMapping @ResponseStatus(HttpStatus.ACCEPTED)public MailDelivery send(@RequestHeader("X-Internal-Key")String provided,@Valid @RequestBody Request r){if(!MessageDigest.isEqual(provided.getBytes(StandardCharsets.UTF_8),key.getBytes(StandardCharsets.UTF_8)))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid internal service key");return service.send(r.to(),r.subject(),r.body());}public record Request(@Email @NotBlank String to,@NotBlank @Size(max=200) String subject,@NotBlank @Size(max=10000) String body){}}
